class TradeId {
    final String book; final long seq;
    TradeId(String book, long seq) { this.book = book; this.seq = seq; }
    @Override public boolean equals(Object o) {
        return o instanceof TradeId t && book.equals(t.book) && seq == t.seq;
    }
    // hashCode NOT overridden: uses identity, different for every object
}

Map<TradeId, String> m = new HashMap<>();
